import type { CourseSentence, CourseLevelId, SentenceLesson } from './courseContent';

type VocabPair = [word: string, meaning: string];
type DialogueTurn = SentenceLesson['dialogue'][number];

const sentence = (
  id: string,
  en: string,
  fa: string,
  pronunciation: string,
  pattern: string,
  vocabulary: VocabPair[],
): CourseSentence => ({
  id,
  en,
  fa,
  pronunciation,
  pattern,
  vocabulary: vocabulary.map(([word, meaning]) => ({ word, meaning })),
});

const turn = (speaker: DialogueTurn['speaker'], text: string, fa: string): DialogueTurn => ({ speaker, text, fa });

const lesson = (
  id: string,
  levelId: CourseLevelId,
  order: number,
  title: string,
  subtitle: string,
  situation: string,
  sentences: CourseSentence[],
  dialogue: DialogueTurn[],
): SentenceLesson => ({ id, levelId, order, title, subtitle, situation, durationMinutes: 12, sentences, dialogue });

